window.GEN_BANK = [{"section": "reading", "type": "sentence_pos", "level": 1, "points": 2, "q": "다음 글을 읽고 ‘비가 올 것 같습니다.’가 들어갈 가장 알맞은 위치를 고르십시오.", "qGl": "Read the following passage and choose the most appropriate position for the sentence ‘비가 올 것 같습니다.’", "passage": "오늘은 날씨가 흐립니다. ㉠ 아침에 창문을 열었습니다. ㉡ 하늘에 구름이 많았습니다. ㉢ 저는 가방에 우산을 넣었습니다. ㉣ 집을 나왔습니다.", "passageGl": "Today the weather is cloudy. ㉠ In the morning I opened the window. ㉡ There were many clouds in the sky. ㉢ I put an umbrella in my bag. ㉣ I left the house.", "options": [{"t": "㉠", "gl": "position 1 (after the first sentence)"}, {"t": "㉡", "gl": "position 2 (after opening the window)"}, {"t": "㉢", "gl": "position 3 (after seeing many clouds)"}, {"t": "㉣", "gl": "position 4 (after packing the umbrella)"}], "correct": 2, "explain": "The sentence ‘비가 올 것 같습니다’ logically follows the observation that there were many clouds, and it explains why the speaker put an umbrella in the bag.", "traps": ["Position 1 is too early because the sky has not been described yet.", "Position 2 is awkward because the speaker has only opened the window and has not mentioned clouds.", "Position 4 is too late because the umbrella has already been packed."], "tip": "문장이 들어갈 위치는 앞뒤 문장의 원인과 결과를 연결해 보세요.", "optExplain": ["오답: ㉠ 앞은 날씨가 흐리다는 첫 문장 뒤인데, 비가 올 것 같다는 판단은 구름을 본 뒤에 나오는 것이 자연스럽습니다.", "오답: ㉡ 앞은 창문을 열었다는 문장 뒤인데, 아직 구름을 보지 않았으므로 비 예상이 어색합니다.", "정답: ㉢ 앞에 하늘에 구름이 많다는 내용이 있으므로 비가 올 것 같다고 예상하고 우산을 넣는 흐름이 자연스럽습니다.", "오답: ㉣ 앞은 이미 우산을 넣은 뒤이므로 비 예상이 먼저 나와야 자연스럽습니다."], "optExplainEn": ["Wrong: Putting it after the first sentence about cloudy weather is less natural because the prediction of rain should come after seeing the clouds.", "Wrong: Putting it after opening the window is awkward because the clouds have not been mentioned yet.", "Correct: Placing it after the sentence about many clouds logically leads to predicting rain and then putting an umbrella in the bag.", "Wrong: Placing it after already packing the umbrella is unnatural because the expectation of rain should come before."], "tipEn": "For sentence-position questions, check how the inserted sentence connects the cause and result before and after.", "freq": 2, "freqNote": "TOPIK I 읽기 31~33 · 문장 위치 파악", "id": "AII-baac88"}, {"section": "reading", "type": "main_idea", "level": 1, "points": 2, "q": "이 글의 주제는 무엇입니까?", "qGl": "What is the topic of this passage?", "passage": "지난 주말에 가족과 함께 바다에 갔습니다. 바다에서 수영을 하고 모래성을 만들었습니다. 저녁에는 맛있는 해산물을 먹었습니다. 아주 즐거웠습니다.", "passageGl": "Last weekend I went to the sea with my family. At the sea we swam and built a sandcastle. In the evening we ate delicious seafood. It was very enjoyable.", "options": [{"t": "주말 가족 여행", "gl": "a weekend family trip"}, {"t": "학교 시험", "gl": "a school exam"}, {"t": "요리 방법", "gl": "a cooking method"}, {"t": "날씨 정보", "gl": "weather information"}], "correct": 0, "explain": "The passage consistently describes what the speaker did with their family on a weekend trip to the sea, so the topic is a weekend family trip.", "traps": ["A school exam is not mentioned at all.", "The passage does not explain how to cook anything.", "No weather information is provided."], "tip": "주제는 글 전체에서 반복되거나 가장 많이 설명하는 대상을 고르세요.", "optExplain": ["정답: 글에서 주말에 가족과 바다에 가서 논 이야기를 했으므로 주말 가족 여행이 주제입니다.", "오답: 학교 시험에 대한 내용은 전혀 나오지 않았습니다.", "오답: 요리 방법을 설명하는 내용이 아닙니다.", "오답: 날씨 정보는 다루지 않았습니다."], "optExplainEn": ["Correct: The passage talks about going to the sea with family on the weekend, so the topic is a weekend family trip.", "Wrong: There is no mention of a school exam.", "Wrong: The passage does not explain a cooking method.", "Wrong: Weather information is not covered."], "tipEn": "For main-idea questions, choose the subject that is consistently described throughout the whole passage.", "freq": 2, "freqNote": "TOPIK I 읽기 25~27 · 중심 생각/주제 파악", "id": "AII-fda31b"}, {"section": "reading", "type": "vocab", "level": 1, "points": 2, "q": "다음 밑줄 친 ‘아주’와 의미가 가장 비슷한 것을 고르십시오.", "qGl": "Choose the option with the closest meaning to the underlined word ‘아주’.", "passage": "이 가방은 아주 큽니다. 그래서 무겁습니다.", "passageGl": "This bag is very big. Therefore it is heavy.", "options": [{"t": "조금", "gl": "a little"}, {"t": "정말", "gl": "really"}, {"t": "빨리", "gl": "quickly"}, {"t": "항상", "gl": "always"}], "correct": 1, "explain": "In this sentence ‘아주’ expresses a high degree, so the closest meaning is ‘정말’, which can also mean ‘really/very’.", "traps": ["‘조금’ means a small degree, which is the opposite of ‘아주’.", "‘빨리’ relates to speed, not degree.", "‘항상’ relates to time, not degree."], "tip": "비슷한 뜻 고르기는 문장에서 그 단어가 강조하는 정도나 상황을 먼저 파악하세요.", "optExplain": ["오답: ‘조금’은 정도가 작다는 뜻이므로 ‘아주’와 반대 의미입니다.", "정답: ‘아주’는 ‘정말’과 비슷하게 정도가 크다는 의미입니다.", "오답: ‘빨리’는 속도가 빠르다는 뜻으로 의미가 다릅니다.", "오답: ‘항상’은 시간의 반복을 나타내는 말로 의미가 다릅니다."], "optExplainEn": ["Wrong: ‘조금’ means a small degree, which is the opposite of ‘아주’.", "Correct: ‘아주’ is similar to ‘정말’ in expressing a high degree.", "Wrong: ‘빨리’ means quickly and has a different meaning.", "Wrong: ‘항상’ means always and refers to repeated time."], "tipEn": "For synonym questions, first identify what the word is emphasizing in the sentence—degree, manner, or time.", "freq": 2, "freqNote": "TOPIK I 읽기 16~18 · 어휘 의미 파악", "id": "AII-503178"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "다음 글을 읽고 맞지 않는 것을 고르십시오.", "qGl": "Read the passage and choose the statement that is not correct.", "passage": "저는 수진입니다. 오늘 엄마하고 시장에 갔습니다. 시장에서 사과하고 우유를 샀습니다. 내일은 학교에 가요.", "passageGl": "I am Sujin. Today I went to the market with my mom. At the market I bought apples and milk. Tomorrow I go to school.", "options": [{"t": "저는 수진입니다.", "gl": "I am Sujin."}, {"t": "오늘 시장에 갔습니다.", "gl": "I went to the market today."}, {"t": "시장에서 빵을 샀습니다.", "gl": "I bought bread at the market."}, {"t": "내일 학교에 가요.", "gl": "I go to school tomorrow."}], "correct": 2, "explain": "The passage says she bought apples and milk at the market, not bread. Therefore, the statement about buying bread is not correct.", "traps": ["Option 1 matches the first sentence.", "Option 2 matches the second sentence.", "Option 4 matches the last sentence."], "tip": "글 속의 정보를 하나씩 비교하세요. 다른 단어(빵/사과)를 조심하세요.", "optExplain": ["오답: 글의 첫 문장과 같습니다.", "오답: 글에서 오늘 엄마하고 시장에 갔다고 했습니다.", "정답: 글에서는 빵을 샀다고 하지 않았습니다. 사과하고 우유를 샀습니다.", "오답: 글의 마지막 문장과 같습니다."], "optExplainEn": ["Wrong: This matches the first sentence of the passage.", "Wrong: The passage says she went to the market today with her mom.", "Correct: The passage does not say she bought bread; she bought apples and milk.", "Wrong: This matches the last sentence of the passage."], "tipEn": "Compare each option with the information in the passage. Watch out for changed words like bread vs. apples.", "freq": 2, "freqNote": "TOPIK I 읽기 31~33 · 짧은 글 이해", "id": "AII-56870e"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "다음 글을 읽고 두 사람이 만나는 곳을 고르십시오.", "qGl": "Read the passage and choose the place where the two people meet.", "passage": "저는 주말에 친구하고 영화를 봅니다. 영화는 두 시에 시작합니다. 우리는 한 시에 영화관에서 만납니다.", "passageGl": "I watch a movie with my friend on the weekend. The movie starts at two o'clock. We meet at the movie theater at one o'clock.", "options": [{"t": "집", "gl": "house"}, {"t": "학교", "gl": "school"}, {"t": "영화관", "gl": "movie theater"}, {"t": "식당", "gl": "restaurant"}], "correct": 2, "explain": "The passage states clearly: 우리는 한 시에 영화관에서 만납니다. So the meeting place is the movie theater.", "traps": ["House is not mentioned as a meeting place.", "School is not mentioned in the passage.", "Restaurant is not mentioned in the passage."], "tip": "장소를 묻는 문제는 '에서' 앞의 단어를 찾으세요.", "optExplain": ["오답: 글에서 만나는 장소로 집이 나오지 않습니다.", "오답: 학교는 글에 나오지 않습니다.", "정답: 글에서 영화관에서 만난다고 했습니다.", "오답: 식당은 글에 나오지 않습니다."], "optExplainEn": ["Wrong: The passage does not mention a house as the meeting place.", "Wrong: School is not mentioned in the passage.", "Correct: The passage says they meet at the movie theater.", "Wrong: Restaurant is not mentioned in the passage."], "tipEn": "For place questions, look for the word before '-에서'.", "freq": 2, "freqNote": "TOPIK I 읽기 34~36 · 장소·정보 파악", "id": "AII-c858b2"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 주말에 책을 ( ) 싶어요.", "passageGl": "I want to ___ a book on the weekend.", "options": [{"t": "읽", "gl": "read (verb stem)"}, {"t": "읽고", "gl": "read (correct with -고 싶다)"}, {"t": "읽어", "gl": "read (connective form)"}, {"t": "읽으", "gl": "read (wrong stem)"}], "correct": 1, "explain": "The pattern -고 싶다 attaches to the verb stem 읽 + 고 = 읽고 싶어요, meaning 'want to read.'", "traps": ["'읽' is only the stem; it cannot connect directly to '-고 싶다'.", "'읽어' is used with '-요' or '-서', not before '-고 싶다'.", "'읽으' is not the correct stem form; the correct stem is '읽'."], "tip": "‘-고 싶다’는 동사 어간 뒤에 붙어요. 받침이 있는 동사도 어간에 바로 '-고'를 붙입니다.", "optExplain": ["오답: '읽'은 동사 어간이지만 '-고 싶다'와 바로 연결할 수 없습니다.", "정답: '읽' + '-고 싶다' → '읽고 싶어요' = 읽기를 원하다.", "오답: '읽어'는 '-어요'나 '-어서'에 쓰이지만 '-고 싶다' 앞에는 쓰지 않습니다.", "오답: '읽으'는 올바른 어간이 아닙니다. '읽'이 어간입니다."], "optExplainEn": ["Wrong: '읽' is only the verb stem and cannot connect directly to '-고 싶다'.", "Correct: '읽' + '-고 싶다' → '읽고 싶어요' means 'want to read'.", "Wrong: '읽어' is used with '-어요' or '-어서', not before '-고 싶다'.", "Wrong: '읽으' is not the correct stem form; the correct stem is '읽'."], "tipEn": "‘-고 싶다’ attaches directly to the verb stem. For verbs with a final consonant, add '-고' to the stem.", "freq": 2, "freqNote": "TOPIK I 읽기 37~40 · 문법·어휘", "id": "AII-f1cebf"}, {"section": "reading", "type": "sentence_pos", "level": 1, "points": 2, "q": "다음 문장이 들어갈 곳을 고르십시오. 그리고 자전거를 탔습니다.", "qGl": "Choose where the following sentence fits. And we rode bicycles.", "passage": "저는 토요일에 친구와 공원에 갔습니다. ( ㉠ ) 공원에서 김밥을 먹었습니다. ( ㉡ ) 우리는 사진을 찍었습니다. ( ㉢ ) 집에 갔습니다. ( ㉣ )", "passageGl": "On Saturday, I went to the park with my friend. (㉠) We ate kimbap at the park. (㉡) We took pictures. (㉢) We went home. (㉣)", "options": [{"t": "㉠", "gl": "position ㉠"}, {"t": "㉡", "gl": "position ㉡"}, {"t": "㉢", "gl": "position ㉢"}, {"t": "㉣", "gl": "position ㉣"}], "correct": 1, "explain": "The sentence 'And we rode bicycles' logically follows the lunch activity and precedes taking pictures, creating a natural sequence of park activities.", "traps": ["Placing the bicycle ride before eating is possible, but the sentence begins with 'And', making it less natural before lunch has been mentioned.", "Placing it after taking pictures creates an awkward order because the statement then interrupts the conclusion of the outing.", "Placing it after going home is illogical because one cannot ride a bicycle after returning home."], "tip": "‘그리고’나 ‘-고’처럼 앞 활동이 끝난 뒤 이어지는 문장을 찾으세요.", "optExplain": ["오답: 식사를 하기 전에 자전거를 타는 것은 ‘그리고’의 흐름과 어울리지 않습니다.", "정답: 점심을 먹은 후에 자전거를 타고 사진을 찍는 순서가 자연스럽습니다.", "오답: 사진을 찍은 다음에 자전거를 타면 집에 가는 흐름이 끊깁니다.", "오답: 집에 간 다음에는 자전거를 탈 수 없습니다."], "optExplainEn": ["Wrong: Riding a bicycle before eating does not match the 'and' flow.", "Correct: The order of eating lunch, riding bicycles, and then taking pictures is natural.", "Wrong: Riding a bicycle after taking pictures interrupts the flow of going home.", "Wrong: You cannot ride a bicycle after going home."], "tipEn": "Look for a sentence that continues after the previous activity using connectors like '그리고' or '-고'.", "freq": 2, "freqNote": "TOPIK I 읽기 31~33 · 문장 위치", "id": "AII-c1fcb0"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 3, "q": "이 사람은 주말에 무엇을 했습니까?", "qGl": "What did this person do on the weekend?", "passage": "지난 주말에 가족과 함께 할머니 댁에 갔습니다. 할머니께서 맛있는 음식을 많이 만들어 주셨습니다. 저는 할머니와 함께 시장에도 갔습니다. 시장에서 과일을 샀습니다.", "passageGl": "Last weekend, I went to my grandmother's house with my family. Grandmother made a lot of delicious food for us. I also went to the market with my grandmother. We bought fruit at the market.", "options": [{"t": "친구를 만났습니다.", "gl": "Met a friend"}, {"t": "할머니 댁에 갔습니다.", "gl": "Went to grandmother's house"}, {"t": "영화를 봤습니다.", "gl": "Watched a movie"}, {"t": "학교에서 공부했습니다.", "gl": "Studied at school"}], "correct": 1, "explain": "The first sentence clearly states that the person went to grandmother's house with family on the weekend.", "traps": ["The passage does not mention meeting a friend; it mentions family and grandmother.", "No movie or watching is mentioned.", "No school or studying is mentioned."], "tip": "첫 문장에서 장소와 사람을 확인하면 주제를 쉽게 찾을 수 있습니다.", "optExplain": ["오답: 친구를 만났다는 내용은 지문에 없습니다. 가족과 할머니 댁에 갔습니다.", "정답: 첫 문장에서 주말에 가족과 함께 할머니 댁에 갔다고 했습니다.", "오답: 영화를 봤다는 내용은 지문에 없습니다.", "오답: 학교에서 공부했다는 내용은 지문에 없습니다."], "optExplainEn": ["Wrong: The passage does not mention meeting a friend; it says they went to grandmother's house with family.", "Correct: The first sentence says they went to grandmother's house with family on the weekend.", "Wrong: There is no mention of watching a movie.", "Wrong: There is no mention of studying at school."], "tipEn": "Check the place and people in the first sentence to easily find the main topic.", "freq": 2, "freqNote": "TOPIK I 읽기 40~42 · 짧은 글 이해", "id": "AII-2f74e8"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 3, "q": "학생들은 무엇을 준비해야 합니까?", "qGl": "What should students prepare?", "passage": "다음 주 수요일에 학교에서 소풍을 갑니다. 장소는 남산공원입니다. 아침 9시까지 학교 운동장에 모이세요. 점심 도시락과 물을 준비하세요.", "passageGl": "Next Wednesday, the school will go on a picnic. The place is Namsan Park. Please gather in the school playground by 9 a.m. Please prepare a lunchbox and water.", "options": [{"t": "책과 공책", "gl": "Books and notebooks"}, {"t": "도시락과 물", "gl": "Lunchbox and water"}, {"t": "우산과 모자", "gl": "Umbrella and hat"}, {"t": "카메라와 가방", "gl": "Camera and bag"}], "correct": 1, "explain": "The notice says participants should prepare a lunchbox and water.", "traps": ["Books and notebooks are not mentioned in the notice.", "Umbrella and hat are not mentioned.", "Camera and bag are not mentioned."], "tip": "안내문은 날짜, 장소, 준비물 순서로 읽으면 핵심 정보를 찾기 쉽습니다.", "optExplain": ["오답: 책과 공책은 준비하라고 하지 않았습니다.", "정답: 안내문에 점심 도시락과 물을 준비하라고 했습니다.", "오답: 우산과 모자는 지문에 없습니다.", "오답: 카메라와 가방은 지문에 없습니다."], "optExplainEn": ["Wrong: The notice does not ask students to bring books and notebooks.", "Correct: The notice says to prepare a lunchbox and water.", "Wrong: An umbrella and hat are not mentioned.", "Wrong: A camera and bag are not mentioned."], "tipEn": "Read notices in the order of date, place, and items to prepare to find key information easily.", "freq": 2, "freqNote": "TOPIK I 읽기 40~42 · 안내문 이해", "id": "AII-a89926"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 아침( ) 빵을 먹습니다.", "passageGl": "I eat bread in the morning.", "options": [{"t": "에", "gl": "time particle 'at/on/in'"}, {"t": "에서", "gl": "location particle 'at/in/on'"}, {"t": "을", "gl": "object particle"}, {"t": "와", "gl": "connective particle 'and/with'"}], "correct": 0, "explain": "The blank follows '아침' (morning), which is a time noun. The particle '에' is used with time expressions to indicate when an action takes place, so '아침에' is correct.", "traps": ["'에서' marks a location where an action occurs, not a time.", "'을' marks an object of a verb, but '아침' is not the object here.", "'와' means 'and/with' and cannot link a time noun to a verb phrase in this context."], "tip": "Remember: time nouns like 아침, 점심, 저녁, 주말 take the particle '에' to express 'at/on/in' the time.", "optExplain": ["정답: '아침'은 시간 명사이므로 시간을 나타내는 조사 '에'가 붙어 '아침에'가 됩니다.", "오답: '에서'는 장소에서 행동이 일어날 때 쓰는 조사이므로 시간 명사인 '아침'에는 알맞지 않습니다.", "오답: '을'은 목적격 조사로, '빵'처럼 동작의 대상에 붙어야 하므로 '아침' 뒤에는 올 수 없습니다.", "오답: '와'는 '~와/과'로 명사와 명사를 연결하거나 함께함을 나타내므로 이 자리에는 어울리지 않습니다."], "optExplainEn": ["Correct: '아침' is a time noun, so the time particle '에' is added to form '아침에'.", "Wrong: '에서' is used when an action occurs at a place, so it does not fit the time noun '아침'.", "Wrong: '을' is an object particle and must attach to the object of an action like '빵', not to '아침'.", "Wrong: '와' links nouns or means 'together with', so it is not suitable in this position."], "tipEn": "Remember: time nouns like morning, lunch, dinner, and weekend take the particle '에' to express 'at/on/in' the time.", "freq": 2, "freqNote": "TOPIK I 읽기 1~4 · 조사/시제", "id": "AII-6a0970"}, {"section": "listening", "type": "intent", "level": 1, "points": 3, "q": "가: 뭘 사고 싶어요?\n나: 저는 운동화가 사고 싶어요.\n가: 그럼, 이 운동화는 어때요?\n나: 좋아요. 이걸로 주세요.", "qGl": "A: What do you want to buy?\nB: I want to buy sneakers.\nA: Then how about these sneakers?\nB: They're good. I'll take these.", "passage": "", "passageGl": "", "options": [{"t": "운동화를 사려고 한다.", "gl": "Intends to buy sneakers."}, {"t": "운동화를 신어 보려고 한다.", "gl": "Intends to try on sneakers."}, {"t": "운동화를 고쳐 주려고 한다.", "gl": "Intends to repair sneakers."}, {"t": "운동화를 보여 주려고 한다.", "gl": "Intends to show sneakers."}], "correct": 0, "explain": "The woman says 'I want to buy sneakers' and 'I'll take these', clearly showing her intention to purchase sneakers.", "traps": ["Option 2: No mention of trying on shoes.", "Option 3: No mention of repairing.", "Option 4: Showing is what the shopkeeper does, not the woman's intention."], "tip": "Listen for key phrases like '사고 싶어요' (want to buy) and '주세요' (please give me) that signal a purchase intention.", "optExplain": ["정답: 여자가 '운동화가 사고 싶어요'라고 말하고 '이걸로 주세요'라고 하여 구매 의도를 분명히 밝혔습니다.", "오답: 신어 보는 행동에 대한 언급이 전혀 없습니다.", "오답: 수리에 관한 말은 한 마디도 나오지 않았습니다.", "오답: 보여 주는 것은 가게 주인의 행동이며, 여자의 의도가 아닙니다."], "optExplainEn": ["Correct: The woman says 'I want to buy sneakers' and 'I'll take these', clearly expressing her intention to buy.", "Wrong: There is no mention of trying them on.", "Wrong: There is no mention of repairing them.", "Wrong: Showing the sneakers is the shopkeeper's action, not the woman's intention."], "tipEn": "Listen for key phrases like '사고 싶어요' (want to buy) and '주세요' (please give me) that signal a purchase intention.", "freq": 2, "freqNote": "TOPIK I 듣기 13~16 · 의도 파악", "audioHint": "나: 저는 운동화가 사고 싶어요.", "id": "AII-af5ebd"}, {"section": "listening", "type": "grammar", "level": 1, "points": 3, "q": "가: 어디에 가요?\n나: 친구를 만나(   ) 학교에 가요.", "qGl": "A: Where are you going?\nB: I'm going to school (   ) meet my friend.", "passage": "", "passageGl": "", "options": [{"t": "-고", "gl": "and (connective)"}, {"t": "-러", "gl": "in order to (purpose)"}, {"t": "-면", "gl": "if/when"}, {"t": "-지만", "gl": "but"}], "correct": 1, "explain": "The phrase '친구를 만나( ) 학교에 가요' requires a purpose connective. '-러' is used with motion verbs to indicate the purpose of going, so '만나러 가요' means 'go to meet'.", "traps": ["Option 1: '-고' simply connects two actions, not expressing purpose.", "Option 3: '-면' is used for conditions, not purpose.", "Option 4: '-지만' means 'but', which does not fit the context."], "tip": "Remember that '-러' is attached to verb stems and followed by motion verbs like 가다, 오다 to express going/coming for that action.", "optExplain": ["오답: '-고'는 두 동작을 단순히 연결하며 목적의 의미가 없습니다.", "정답: '-러'는 동작 동사와 결합하여 '가다'의 목적을 나타냅니다. '만나러 가요'는 만나기 위해 간다는 뜻입니다.", "오답: '-면'은 조건을 나타내며 문장에 적합하지 않습니다.", "오답: '-지만'은 '그러나'의 뜻으로 글의 흐름상 맞지 않습니다."], "optExplainEn": ["Wrong: '-고' merely connects two actions without expressing purpose.", "Correct: '-러' indicates the purpose of going with motion verbs, so '만나러 가요' means 'go to meet'.", "Wrong: '-면' is used for conditions, not purpose.", "Wrong: '-지만' means 'but' and doesn't fit the context."], "tipEn": "Remember that '-러' is attached to verb stems and followed by motion verbs like 가다, 오다 to express going/coming for that action.", "freq": 2, "freqNote": "TOPIK I 듣기 23~25 · 문법", "audioHint": "나: 친구를 만나러 학교에 가요.", "id": "AII-9d7d7e"}, {"section": "listening", "type": "comprehension", "level": 1, "points": 4, "q": "가: 이번 주말에 뭐 할 거예요?\n나: 친구랑 같이 테니스를 칠 거예요.\n가: 좋겠네요. 저도 테니스를 배우고 싶어요.\n나: 그럼 같이 배워요.", "qGl": "A: What are you going to do this weekend?\nB: I'm going to play tennis with a friend.\nA: That sounds great. I want to learn tennis too.\nB: Then let's learn together.", "passage": "", "passageGl": "", "options": [{"t": "남자는 주말에 영화를 볼 것이다.", "gl": "The man will watch a movie on the weekend."}, {"t": "여자는 테니스를 칠 것이다.", "gl": "The woman will play tennis."}, {"t": "남자는 친구와 테니스를 칠 것이다.", "gl": "The man will play tennis with his friend."}, {"t": "여자는 테니스를 배우지 않을 것이다.", "gl": "The woman will not learn tennis."}], "correct": 2, "explain": "The man says, 'I'm going to play tennis with a friend,' so option 3 matches exactly.", "traps": ["Option 1: The man didn't mention a movie.", "Option 2: The woman wants to learn, not play, and no mention of her playing.", "Option 4: The woman expresses interest in learning and the man suggests they learn together, so she is likely to learn."], "tip": "Focus on who is speaking and what each person says. Match the detail precisely; don't confuse the subjects.", "optExplain": ["오답: 남자가 영화를 볼 거라고 말하지 않았습니다.", "오답: 여자는 테니스를 배우고 싶다고 했지, 직접 치겠다고 한 말은 없습니다.", "정답: 남자가 '친구랑 같이 테니스를 칠 거예요'라고 말했기 때문에 내용이 일치합니다.", "오답: 여자는 배우고 싶다고 했고, 남자가 같이 배우자고 하여 배울 가능성이 높습니다."], "optExplainEn": ["Wrong: The man didn't say anything about watching a movie.", "Wrong: The woman only said she wants to learn, not that she will play.", "Correct: The man clearly said 'I'm going to play tennis with a friend,' matching this option.", "Wrong: The woman expressed a desire to learn and the man invited her to learn together, so she likely will learn."], "tipEn": "Focus on who is speaking and what each person says. Match the detail precisely; don't confuse the subjects.", "freq": 2, "freqNote": "TOPIK I 듣기 27~30 · 내용 이해", "audioHint": "나: 친구랑 같이 테니스를 칠 거예요.", "id": "AII-f2b457"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "남자: 지난 주말에 뭐 했어요?\n여자: 친구하고 영화를 봤어요.\n남자: 영화가 재미있었어요?\n여자: 네, 아주 재미있었어요.\n무엇에 대해 이야기하고 있습니까?", "qGl": "Man: What did you do last weekend? Woman: I saw a movie with a friend. Man: Was the movie fun? Woman: Yes, it was really fun. What are they talking about?", "passage": "", "passageGl": "", "audioHint": "남자: 주말에 뭐 했어요? 여자: 친구하고 영화 봤어요.", "options": [{"t": "영화", "gl": "movie"}, {"t": "운동", "gl": "exercise"}, {"t": "쇼핑", "gl": "shopping"}, {"t": "여행", "gl": "travel"}], "correct": 0, "explain": "The dialogue contains repeated references to 영화, such as '영화를 봤어요' and '영화가 재미있었어요?', so the topic is movie.", "traps": ["운동 is not mentioned at all in the conversation.", "쇼핑 is not mentioned at all in the conversation.", "여행 is not mentioned at all in the conversation."], "tip": "Listen for repeated nouns in TOPIK I listening topic questions; the repeated word is usually the answer.", "optExplain": ["정답: 두 사람이 ‘영화를 봤어요’, ‘영화가 재미있었어요’라고 말하므로 영화에 대해 이야기하고 있습니다.", "오답: ‘운동’은 대화에 나오지 않았습니다.", "오답: ‘쇼핑’은 대화에 나오지 않았습니다.", "오답: ‘여행’은 대화에 나오지 않았습니다."], "optExplainEn": ["Correct: They talk about a movie, saying 'I saw a movie' and 'Was the movie fun?'", "Wrong: 'Exercise' does not appear in the dialogue.", "Wrong: 'Shopping' does not appear in the dialogue.", "Wrong: 'Travel' does not appear in the dialogue."], "tipEn": "Listen for repeated nouns in TOPIK I listening topic questions; the repeated word is usually the answer.", "freq": 2, "freqNote": "TOPIK I 듣기 4~6 · 주제 고르기", "id": "AII-534b5d"}, {"section": "listening", "type": "grammar", "level": 1, "points": 2, "q": "가: 뭐 먹고 싶어요?\n나: ________", "qGl": "A: What do you want to eat? B: ________", "passage": "", "passageGl": "", "audioHint": "가: 뭐 먹고 싶어요? 나: ...", "options": [{"t": "비빔밥을 먹고 싶어요.", "gl": "I want to eat bibimbap."}, {"t": "비빔밥을 먹었어요.", "gl": "I ate bibimbap."}, {"t": "비빔밥을 먹을 수 있어요.", "gl": "I can eat bibimbap."}, {"t": "비빔밥을 먹지 마세요.", "gl": "Don't eat bibimbap."}], "correct": 0, "explain": "The question uses -고 싶어요 to ask what someone wants to eat, so the correct answer must also use -고 싶어요.", "traps": ["먹었어요 is past tense, so it does not answer a question about what someone wants.", "먹을 수 있어요 expresses ability, not desire.", "먹지 마세요 is a prohibition and cannot be B's answer to A's question."], "tip": "When a TOPIK I listening question asks '뭐 -고 싶어요?', choose the response that repeats '-고 싶어요'.", "optExplain": ["정답: ‘뭐 먹고 싶어요?’라고 원하는 것을 물었으므로 ‘먹고 싶어요’로 대답하는 것이 맞습니다.", "오답: ‘먹었어요’는 과거를 말하므로 원하는 것을 묻는 질문에 어울리지 않습니다.", "오답: ‘먹을 수 있어요’는 가능을 말하므로 질문과 연결되지 않습니다.", "오답: ‘먹지 마세요’는 금지를 말하므로 질문에 대한 대답이 아닙니다."], "optExplainEn": ["Correct: Since the question asks what you want to eat, answering with 'want to eat' is correct.", "Wrong: 'Ate' is past tense, so it does not fit a question about desire.", "Wrong: 'Can eat' expresses ability, not desire.", "Wrong: 'Don't eat' is a prohibition, not an answer to the question."], "tipEn": "When a TOPIK I listening question asks '뭐 -고 싶어요?', choose the response that repeats '-고 싶어요'.", "freq": 2, "freqNote": "TOPIK I 듣기 7~10 · 문법형 대답 고르기", "id": "AII-14a5d1"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "남자: 오늘 날씨가 어때요?\n여자: 눈이 와요. 아주 추워요.\n남자: 따뜻한 옷을 입으세요.\n여자: 네, 고마워요.\n무엇에 대해 이야기하고 있습니까?", "qGl": "Man: How is the weather today? Woman: It's snowing. It's very cold. Man: Wear warm clothes. Woman: Yes, thank you. What are they talking about?", "passage": "", "passageGl": "", "audioHint": "남자: 오늘 날씨 어때요? 여자: 눈이 와요. 아주 추워요.", "options": [{"t": "날씨", "gl": "weather"}, {"t": "음식", "gl": "food"}, {"t": "가족", "gl": "family"}, {"t": "운동", "gl": "exercise"}], "correct": 0, "explain": "The dialogue mentions 날씨, 눈, and 추워요, all of which point to the topic of weather.", "traps": ["음식 is not mentioned in the dialogue.", "가족 is not mentioned in the dialogue.", "운동 is not mentioned in the dialogue."], "tip": "In TOPIK I listening topic questions, the first question often reveals the topic: '날씨가 어때요?' means the topic is weather.", "optExplain": ["정답: 대화에서 ‘날씨’, ‘눈’, ‘추워요’를 말하므로 날씨에 대해 이야기하고 있습니다.", "오답: ‘음식’은 대화에 나오지 않았습니다.", "오답: ‘가족’은 대화에 나오지 않았습니다.", "오답: ‘운동’은 대화에 나오지 않았습니다."], "optExplainEn": ["Correct: The dialogue mentions weather, snow, and cold, so the topic is weather.", "Wrong: 'Food' does not appear in the dialogue.", "Wrong: 'Family' does not appear in the dialogue.", "Wrong: 'Exercise' does not appear in the dialogue."], "tipEn": "In TOPIK I listening topic questions, the first question often reveals the topic: '날씨가 어때요?' means the topic is weather.", "freq": 2, "freqNote": "TOPIK I 듣기 4~6 · 주제 고르기", "id": "AII-af21e6"}, {"section": "listening", "type": "place", "level": 1, "points": 2, "q": "여자: 지금 어디에 가요? \n남자: 배가 고파서 점심을 먹으러 식당에 가요.", "qGl": "Woman: Where are you going now? \nMan: I'm hungry, so I'm going to the restaurant to eat lunch.", "passage": "", "passageGl": "", "options": [{"t": "학교", "gl": "school"}, {"t": "식당", "gl": "restaurant"}, {"t": "서점", "gl": "bookstore"}, {"t": "병원", "gl": "hospital"}], "correct": 1, "explain": "The man says he is going to the restaurant (식당) to eat lunch because he is hungry. This directly matches the place being asked about.", "traps": ["학교 (school) might be confused with a daily routine place, but no mention of studying or classes.", "서점 (bookstore) is unrelated to eating lunch, so it’s not implied.", "병원 (hospital) is not a place to eat a meal, and there’s no health-related context."], "tip": "In place-asking conversations, listen for destination-related verbs (e.g., 가다) and purpose markers like -(으)러. Keywords like ‘먹으러’ and ‘식당’ will directly point to the location.", "optExplain": ["오답: 대화에서 학교와 관련된 말이 없습니다.", "정답: 남자가 '식당에 가요'라고 말합니다.", "오답: 서점에 대한 이야기가 나오지 않습니다.", "오답: 병원은 식사와 무관합니다."], "optExplainEn": ["Wrong: There is no mention of school in the dialogue.", "Correct: The man says 'I'm going to the restaurant'.", "Wrong: There is no talk about a bookstore.", "Wrong: A hospital is not related to eating."], "tipEn": "In place-asking conversations, listen for destination-related verbs (e.g., 가다) and purpose markers like -(으)러. Keywords like ‘먹으러’ and ‘식당’ will directly point to the location.", "freq": 2, "freqNote": "TOPIK I 듣기 6~8 · 장소 고르기", "audioHint": "여자: 어디에 가요? 남자: 점심 먹으러 식당에 가요.", "id": "AII-675e76"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "남자: 오늘 날씨가 정말 춥네요. \n여자: 네, 바람도 많이 불어요. 감기 조심하세요.", "qGl": "Man: The weather is really cold today. \nWoman: Yes, and the wind is blowing a lot. Be careful not to catch a cold.", "passage": "", "passageGl": "", "options": [{"t": "음식", "gl": "food"}, {"t": "쇼핑", "gl": "shopping"}, {"t": "날씨", "gl": "weather"}, {"t": "운동", "gl": "exercise"}], "correct": 2, "explain": "The conversation revolves around the cold weather, wind, and a warning about catching a cold, all indicators of the topic being ‘weather’.", "traps": ["음식 (food) is not mentioned at all; no talk of eating or dishes.", "쇼핑 (shopping) is unrelated; nothing about buying or stores.", "운동 (exercise) is not referenced; no mention of physical activity."], "tip": "For topic-identification questions, focus on repeated nouns and adjectives. Here ‘날씨’, ‘춥네요’, ‘바람’, ‘감기’ all cluster around weather. Related expressions often signal the theme.", "optExplain": ["오답: 대화에서 음식에 관한 말이 없습니다.", "오답: 쇼핑과 관련된 표현이 전혀 없습니다.", "정답: '날씨가 춥네요'와 '바람', '감기' 등 날씨 주제 대화입니다.", "오답: 운동에 대한 내용은 나오지 않습니다."], "optExplainEn": ["Wrong: There is no talk about food in the dialogue.", "Wrong: No expressions related to shopping appear.", "Correct: 'The weather is cold', 'wind', and 'cold' make the topic weather.", "Wrong: No content about exercise is mentioned."], "tipEn": "For topic-identification questions, focus on repeated nouns and adjectives. Here ‘날씨’, ‘춥네요’, ‘바람’, ‘감기’ all cluster around weather. Related expressions often signal the theme.", "freq": 2, "freqNote": "TOPIK I 듣기 9~12 · 주제 고르기", "audioHint": "남자: 날씨가 춥네요. 여자: 네, 바람도 불어요. 감기 조심하세요.", "id": "AII-b49da8"}, {"section": "reading", "type": "main_idea", "level": 3, "points": 2, "q": "이 글의 중심 생각으로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate main idea of this passage.", "passage": "요즘 많은 직장인들이 점심 식사 후에 커피를 마신다. 그런데 커피 대신 짧은 산책을 하면 오후에 더 집중할 수 있다. 실제로 한 연구에 따르면 10분 정도 걸으면 머리가 맑아지고 피로가 줄어든다고 한다. 따라서 바쁘더라도 점심시간에 잠깐 밖에 나가는 것이 좋다.", "passageGl": "These days many office workers drink coffee after lunch. However, if they take a short walk instead of coffee, they can concentrate better in the afternoon. In fact, according to one study, walking for about 10 minutes clears the mind and reduces fatigue. Therefore, even if you are busy, it is good to go outside briefly during lunchtime.", "options": [{"t": "점심 식사 후 커피를 마시는 습관을 바꿔야 한다.", "gl": "We should change the habit of drinking coffee after lunch."}, {"t": "직장인들은 점심시간에 잠을 자야 한다.", "gl": "Office workers should sleep during lunchtime."}, {"t": "점심시간에 짧은 산책을 하면 오후 업무에 도움이 된다.", "gl": "Taking a short walk at lunchtime helps with afternoon work."}, {"t": "커피보다 산책이 건강에 더 나쁘다.", "gl": "Walking is worse for health than coffee."}], "correct": 2, "explain": "The passage contrasts drinking coffee with taking a short walk, cites research that walking clears the mind and reduces fatigue, and concludes that you should go outside briefly during lunch. This makes the benefit of a short lunchtime walk the central idea.", "traps": ["It overstates the passage by focusing on changing a coffee habit rather than on the recommended action.", "It introduces sleeping, which is never mentioned in the passage.", "It reverses the health comparison by saying walking is worse than coffee."], "tip": "For a main-idea question, look for the final recommendation or conclusion and check which option matches the repeated topic plus that conclusion.", "optExplain": ["오답: 커피 습관을 바꾸라는 내용은 글의 일부가 아니라 중심 생각이 아닙니다.", "오답: 점심시간에 잠을 자라는 내용은 글에 나오지 않습니다.", "정답: 짧은 산책이 오후 집중과 피로 감소에 도움이 된다는 내용이 글 전체에서 말하는 핵심입니다.", "오답: 산책이 커피보다 건강에 나쁘다는 것은 글의 내용과 반대입니다."], "optExplainEn": ["Wrong: Changing the coffee habit is not the central idea; it is only part of the passage.", "Wrong: Sleeping during lunchtime is never mentioned in the passage.", "Correct: The core message of the passage is that a short walk helps with afternoon concentration and reduces fatigue.", "Wrong: The claim that walking is worse for health than coffee contradicts the passage."], "tipEn": "For a main-idea question, look for the final recommendation or conclusion and check which option matches the repeated topic plus that conclusion.", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 중심 생각 고르기", "id": "AIII-b04d34"}, {"section": "reading", "type": "main_idea", "level": 3, "points": 2, "q": "이 글의 중심 내용으로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate central content of this passage.", "passage": "우리 아파트 관리사무소에서는 다음 달부터 지하 주차장의 조명을 교체합니다. 공사 기간 동안 지하 주차장 일부 구역은 이용할 수 없으며, 차량은 지상 주차장을 이용해 주시기 바랍니다. 공사는 오전 9시부터 오후 6시까지 진행됩니다. 입주민 여러분의 양해를 부탁드립니다.", "passageGl": "Our apartment management office will replace the lighting in the underground parking lot starting next month. During the construction period, some areas of the underground parking lot will be unavailable, and vehicles should use the ground parking lot. The construction will take place from 9 a.m. to 6 p.m. We ask for residents' understanding.", "options": [{"t": "지하 주차장 조명 공사가 있어 지상 주차장을 이용해야 한다.", "gl": "Because of underground parking lot lighting construction, residents should use the ground parking lot."}, {"t": "아파트 지하 주차장을 새로 만든다.", "gl": "The apartment is building a new underground parking lot."}, {"t": "지상 주차장의 조명을 교체한다.", "gl": "The ground parking lot lighting will be replaced."}, {"t": "공사 기간 동안 지하 주차장을 무료로 이용할 수 있다.", "gl": "During construction, the underground parking lot can be used for free."}], "correct": 0, "explain": "The notice announces underground parking lighting replacement, states that some underground areas cannot be used during construction, and directs vehicles to the ground parking lot. This required action is the central content.", "traps": ["It introduces building a new underground parking lot, which is not mentioned.", "It incorrectly says the ground parking lot lighting will be replaced; the replacement is in the underground parking lot.", "It contradicts the notice by saying the underground parking lot can be used for free during construction."], "tip": "In announcement-type readings, identify who must do what. The correct main idea usually includes the requested action.", "optExplain": ["정답: 지하 주차장 조명 교체 공사로 일부 구역을 이용할 수 없어 지상 주차장을 이용하라는 안내가 중심 내용입니다.", "오답: 지하 주차장을 새로 만든다는 내용은 글에 없습니다.", "오답: 조명을 교체하는 곳은 지상이 아니라 지하 주차장입니다.", "오답: 공사 기간 동안 지하 주차장 일부 구역을 이용할 수 없으므로 무료 이용은 틀립니다."], "optExplainEn": ["Correct: The notice's central content is that some underground parking areas are closed due to lighting construction, so residents should use the ground parking lot.", "Wrong: Building a new underground parking lot is not mentioned in the passage.", "Wrong: The lighting being replaced is in the underground parking lot, not the ground parking lot.", "Wrong: Since some underground areas cannot be used during construction, free use is incorrect."], "tipEn": "In announcement-type readings, identify who must do what. The correct main idea usually includes the requested action.", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 중심 내용 고르기", "id": "AIII-917c61"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "회사에 가는 길에 넘어져서 커피를 쏟을 ( ).", "passageGl": "On the way to work, I tripped and almost spilled my coffee.", "options": [{"t": "뻔했다", "gl": "almost did"}, {"t": "중이다", "gl": "in the middle of"}, {"t": "지 됐다", "gl": "has been since"}, {"t": "다가", "gl": "while doing and then"}], "correct": 0, "explain": "The sentence needs a grammar form meaning an action almost happened but did not actually happen. '-(으)ㄹ 뻔했다' expresses exactly that, so '커피를 쏟을 뻔했다' is natural.", "traps": ["'-는 중이다' indicates an action is in progress and would require '쏟는 중이다', not '쏟을 중이다'.", "'-(으)ㄴ 지' is used with time expressions like '몇 달이 됐다', so it does not fit.", "'-다가' indicates a change from one action to another, not an almost-happened event."], "tip": "For 'almost happened but did not' situations, use '-(으)ㄹ 뻔했다'. The preceding verb is in the future-modifier form.", "optExplain": ["정답: '-을 뻔했다'는 어떤 일이 거의 일어날 뻔했지만 실제로는 일어나지 않았음을 나타내므로 '커피를 쏟을 뻔했다'가 자연스럽습니다.", "오답: '-는 중이다'는 동작이 진행 중임을 나타내므로 '쏟는 중이다'가 되어야 자연스럽고 문맥에 맞지 않습니다.", "오답: '-(으)ㄴ 지'는 시간의 경과를 나타내므로 뒤에 '몇 달이 됐다' 같은 표현이 필요합니다.", "오답: '-다가'는 앞의 동작이 중단되고 다른 동작으로 바뀜을 나타내므로 어울리지 않습니다."], "optExplainEn": ["Correct: '-(으)ㄹ 뻔했다' expresses that an action almost happened but did not actually happen, so '커피를 쏟을 뻔했다' is natural.", "Wrong: '-는 중이다' indicates progressive action, so it would need to be '쏟는 중이다' and does not fit the context.", "Wrong: '-(으)ㄴ 지' indicates elapsed time and needs a phrase like '몇 달이 됐다' after it.", "Wrong: '-다가' indicates a shift from one action to another, so it is not suitable here."], "tipEn": "For 'almost happened but did not' situations, use '-(으)ㄹ 뻔했다'. The preceding verb is in the future-modifier form.", "freq": 2, "freqNote": "TOPIK II 읽기 1~4 · 문법 빈칸 채우기", "id": "AIII-130dfa"}, {"section": "reading", "type": "vocab", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.\n요즘 회사 일이 많아서 몸이 많이 ( ).", "qGl": "Choose the most appropriate word to fill in the blank.\nThese days I have a lot of work, so my body is very ___.", "passage": "", "passageGl": "", "options": [{"t": "지쳤다", "gl": "became tired"}, {"t": "늘었다", "gl": "increased"}, {"t": "모였다", "gl": "gathered"}, {"t": "나아졌다", "gl": "improved"}], "correct": 0, "explain": "The correct answer is '지쳤다' because it expresses becoming physically tired, matching the situation of having a lot of work.", "traps": ["'늘었다' means an increase in number, not a physical state, so it doesn’t fit '몸이 많이'.", "'모였다' means gathered, which cannot describe a body condition caused by work.", "'나아졌다' means improved, which contradicts the negative consequence of having too much work."], "tip": "For vocabulary fill-in-the-blank questions, read the whole sentence to identify the cause and result, then choose the word that logically completes the meaning.", "optExplain": ["정답: ‘지쳤다’는 몸이나 마음의 힘이 빠져 힘들어진 상태를 뜻해 일이 많아 몸이 힘들다는 문맥에 맞습니다.", "오답: ‘늘었다’는 수나 양이 많아졌다는 뜻으로 몸의 상태를 나타내기에 어색합니다.", "오답: ‘모였다’는 사람이나 사물이 한곳에 모인다는 뜻으로 문맥과 맞지 않습니다.", "오답: ‘나아졌다’는 상태가 좋아졌다는 뜻인데, 일이 많아서 힘들다는 원인과 결과가 어울리지 않습니다."], "optExplainEn": ["Correct: '지쳤다' means a state of being exhausted, which fits the context that the body is tired due to a lot of work.", "Wrong: '늘었다' means increased in number or amount, so it is awkward to describe physical condition.", "Wrong: '모였다' means gathered, which does not fit the context.", "Wrong: '나아졌다' means improved, but the cause-and-effect with being busy and tired does not match."], "tipEn": "For vocabulary fill-in-the-blank questions, read the whole sentence to identify the cause and result, then choose the word that logically completes the meaning.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 빈칸 어휘 고르기", "id": "AIII-021a04"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.\n비가 많이 와서 하마터면 약속에 늦을 ( ).", "qGl": "Choose the most appropriate grammar to fill in the blank.\nIt rained a lot, so I almost ___ late for the appointment.", "passage": "", "passageGl": "", "options": [{"t": "뻔했다", "gl": "almost did"}, {"t": "것 같다", "gl": "seems like"}, {"t": "수밖에 없다", "gl": "have no choice but to"}, {"t": "적이 없다", "gl": "have never done"}], "correct": 0, "explain": "The correct answer is '뻔했다' because it expresses that the speaker almost became late due to rain, which matches the adverb '하마터면'.", "traps": ["'것 같다' is for guessing, not for an event that nearly happened in the past.", "'수밖에 없다' is about unavoidable action, not about almost being late.", "'적이 없다' refers to lack of past experience, not a near miss."], "tip": "Remember that '하마터면' is often used with '-(으)ㄹ 뻔했다' to indicate a close call or near accident.", "optExplain": ["정답: '-(으)ㄹ 뻔했다'는 어떤 일이 실제로 일어나지는 않았지만 거의 일어날 정도였음을 나타내어 '하마터면'과 잘 어울립니다.", "오답: '-(으)ㄹ 것 같다'는 추측을 나타내므로 과거에 거의 늦었던 상황을 표현하기에는 어색합니다.", "오답: '-(으)ㄹ 수밖에 없다'는 다른 방법이 없음을 나타내므로 ‘하마터면’과 의미가 맞지 않습니다.", "오답: '-(으)ㄴ 적이 없다'는 과거의 경험이 없음을 나타내므로 문맥에 맞지 않습니다."], "optExplainEn": ["Correct: '-(으)ㄹ 뻔했다' expresses that something almost happened but did not actually happen, so it pairs naturally with '하마터면'.", "Wrong: '-(으)ㄹ 것 같다' indicates a guess or assumption, so it is awkward for describing a past situation that almost occurred.", "Wrong: '-(으)ㄹ 수밖에 없다' means having no choice but to do something, which does not fit with '하마터면'.", "Wrong: '-(으)ㄴ 적이 없다' means having never done something, which does not match the context."], "tipEn": "Remember that '하마터면' is often used with '-(으)ㄹ 뻔했다' to indicate a close call or near accident.", "freq": 2, "freqNote": "TOPIK II 읽기 3~4 · 빈칸 문법 고르기", "id": "AIII-92ec76"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 3, "q": "도서관을 이용할 수 없는 이유는 무엇입니까?", "qGl": "Why is the library unavailable?", "passage": "시립 도서관에서 알려 드립니다. 이번 주 토요일과 일요일에는 도서관 내부 공사가 진행됩니다. 공사 기간 중에는 책을 빌리거나 열람실을 이용할 수 없습니다. 이용에 불편을 드려 죄송합니다.", "passageGl": "The city library announces: This Saturday and Sunday, interior construction will take place. During the construction period, you cannot borrow books or use the reading rooms. We apologize for the inconvenience.", "options": [{"t": "도서관 내부 공사가 있기 때문이다", "gl": "Because there is interior construction"}, {"t": "새 책을 정리하고 있기 때문이다", "gl": "Because they are organizing new books"}, {"t": "도서관 직원 연수가 있기 때문이다", "gl": "Because there is staff training"}, {"t": "날씨가 좋지 않기 때문이다", "gl": "Because the weather is bad"}], "correct": 0, "explain": "The correct answer is 'interior construction' because the notice explicitly says the library cannot be used during the construction period.", "traps": ["'Organizing new books' is not mentioned in the passage.", "'Staff training' is not mentioned in the passage.", "'Bad weather' is not mentioned in the passage."], "tip": "In notice-type reading questions, look for time expressions and the main verb phrase (e.g., '이용할 수 없습니다') to identify the reason.", "optExplain": ["정답: 공사 기간 중에는 책을 빌리거나 열람실을 이용할 수 없다고 했으므로 도서관 내부 공사가 이용 불가의 원인입니다.", "오답: 새 책 정리에 대한 내용은 글에 전혀 언급되지 않았습니다.", "오답: 직원 연수에 대한 내용은 글에 전혀 언급되지 않았습니다.", "오답: 날씨에 대한 내용은 글에 전혀 언급되지 않았습니다."], "optExplainEn": ["Correct: The text states that during construction you cannot borrow books or use the reading rooms, so the interior construction is the reason.", "Wrong: Organizing new books is never mentioned in the passage.", "Wrong: Staff training is never mentioned in the passage.", "Wrong: Bad weather is never mentioned in the passage."], "tipEn": "In notice-type reading questions, look for time expressions and the main verb phrase (e.g., '이용할 수 없습니다') to identify the reason.", "freq": 2, "freqNote": "TOPIK II 읽기 9~12 · 짧은 안내문 이해", "id": "AIII-90e597"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate answer for the blank.", "passage": "영수는 회사에 (      ) 3년이 되었다.", "passageGl": "Youngsu has been working at the company for 3 years.", "options": [{"t": "다닌 지", "gl": "since he started working"}, {"t": "다니는 데다가", "gl": "in addition to working"}, {"t": "다닌 척", "gl": "pretending to work"}, {"t": "다닐 뻔했다", "gl": "almost went to work"}], "correct": 0, "explain": "The grammar pattern '-(으)ㄴ 지' is used to express the amount of time that has passed since an action happened. In this sentence, '다닌 지 3년이 되었다' means it has been three years since he started working at the company.", "traps": ["'-는 데다가' means 'in addition to' and does not fit with a time expression like '3년이 되었다'.", "'-ㄴ 척' means 'pretending to do' and would create an illogical meaning: 'pretending to work for 3 years'.", "'-ㄹ 뻔했다' means 'almost did' and cannot be used with a current state of three years having passed."], "tip": "Remember that '-(으)ㄴ 지' is always followed by a time phrase such as '3년이 되었다' or '한 달이 지났다'.", "optExplain": ["정답: '다닌 지'는 어떤 일이 일어난 후 지난 시간을 나타내는 '-(으)ㄴ 지' 표현으로, 회사에 다니기 시작한 지 3년이 되었다는 뜻이 되어 자연스럽습니다.", "오답: '다니는 데다가'는 '~하는 것에 더하여'라는 뜻이므로 시간 표현과 어울리지 않습니다.", "오답: '다닌 척'은 '다니는 것처럼 꾸미다'라는 뜻이 되어 문장 의미가 이상해집니다.", "오답: '다닐 뻔했다'는 '거의 다닐 뻔했다'는 뜻으로, 이미 3년이 지난 현재 상태를 나타낼 수 없습니다."], "optExplainEn": ["Correct: '다닌 지' uses the pattern '-(으)ㄴ 지' which expresses the time that has passed since an action occurred, so the sentence naturally means it has been three years since he started working at the company.", "Wrong: '다니는 데다가' means 'in addition to doing' and does not fit with a time expression.", "Wrong: '다닌 척' would mean 'pretending to go to work', making the sentence illogical.", "Wrong: '다닐 뻔했다' means 'almost went to work' and cannot describe a current state after three years have passed."], "tipEn": "Remember that '-(으)ㄴ 지' is always followed by a time phrase such as '3년이 되었다' or '한 달이 지났다'.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 문법", "id": "AIII-186268"}, {"section": "reading", "type": "vocab", "level": 3, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate answer for the blank.", "passage": "회의에서 의견이 서로 달라서 (      )이/가 생겼다.", "passageGl": "At the meeting, opinions differed, so a conflict arose.", "options": [{"t": "갈등", "gl": "conflict"}, {"t": "참석", "gl": "attendance"}, {"t": "예산", "gl": "budget"}, {"t": "휴가", "gl": "vacation"}], "correct": 0, "explain": "The sentence describes a situation where opinions differ, which naturally leads to '갈등' (conflict). The other words do not fit the context of disagreement.", "traps": ["'참석' means attendance and refers to being present, not a result of differing opinions.", "'예산' means budget, which is unrelated to the disagreement in the meeting.", "'휴가' means vacation, which does not logically follow from differing opinions at a meeting."], "tip": "Learn common abstract nouns like '갈등' (conflict), '의견' (opinion), and '예산' (budget) because they often appear in reading passages about work and society.", "optExplain": ["정답: '갈등'은 서로 생각이 달라서 생기는 충돌을 뜻하므로 회의에서 의견이 다르다는 내용과 자연스럽게 연결됩니다.", "오답: '참석'은 '모임에 참여함'을 뜻하는 말로, 의견 차이로 생기는 결과와 어울리지 않습니다.", "오답: '예산'은 돈이나 비용에 관련된 단어이므로 의견이 다르다는 내용과 관련이 없습니다.", "오답: '휴가'는 쉬는 기간을 뜻하는 단어로, 회의에서 의견이 다르다는 상황과 연결되지 않습니다."], "optExplainEn": ["Correct: '갈등' means a clash caused by different opinions, so it naturally fits the context of differing opinions at a meeting.", "Wrong: '참석' means attendance or being present, which is not a result of differing opinions.", "Wrong: '예산' means budget, which is unrelated to the disagreement in the meeting.", "Wrong: '휴가' means vacation, which does not logically follow from differing opinions at a meeting."], "tipEn": "Learn common abstract nouns like '갈등' (conflict), '의견' (opinion), and '예산' (budget) because they often appear in reading passages about work and society.", "freq": 2, "freqNote": "TOPIK II 읽기 3~4 · 어휘", "id": "AIII-ca43f8"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 2, "q": "윗글의 내용과 같은 것을 고르십시오.", "qGl": "Choose the statement that matches the content of the passage.", "passage": "요즘 많은 사람들이 건강을 지키기 위해 규칙적으로 운동을 하고 있다. 하지만 운동을 처음 시작하는 사람들은 무리하게 운동을 해서 오히려 몸을 다치기도 한다. 전문가들은 자신의 체력에 맞는 운동을 선택하고 충분한 휴식을 취하는 것이 중요하다고 말한다.", "passageGl": "These days, many people exercise regularly to stay healthy. However, people who are new to exercise sometimes overdo it and get injured. Experts say it is important to choose an exercise that fits one's physical strength and to get enough rest.", "options": [{"t": "운동을 하면 누구나 부상을 입는다.", "gl": "Everyone who exercises gets injured."}, {"t": "자신의 체력에 맞는 운동을 하는 것이 좋다.", "gl": "It is good to do exercise that fits one's physical strength."}, {"t": "건강을 위해 운동을 하지 않는 것이 낫다.", "gl": "It is better not to exercise for health."}, {"t": "운동을 시작하면 몸을 다치지 않는다.", "gl": "If you start exercising, you will not get injured."}], "correct": 1, "explain": "The passage says experts recommend choosing an exercise that fits one's physical strength and taking enough rest, so option 1 matches the content. The other options are not supported by the text.", "traps": ["Option 0 says everyone who exercises gets injured, but the passage says people who overdo it may get injured, not everyone.", "Option 2 says it is better not to exercise, but the passage states many people exercise to stay healthy and experts only advise doing it safely.", "Option 3 says starting exercise prevents injury, which is the opposite of the passage's warning about overdoing it."], "tip": "For 'choose the same content' questions, compare each option with the passage word by word and avoid extreme words like '누구나' (everyone) or '절대로' (never).", "optExplain": ["정답: 지문에서 전문가들이 체력에 맞는 운동을 선택하라고 했으므로 '자신의 체력에 맞는 운동을 하는 것이 좋다'는 내용과 일치합니다.", "오답: 지문은 무리한 운동을 할 때 부상을 입을 수 있다고 했지, 운동을 하면 누구나 부상을 입는다고 하지 않았습니다.", "오답: 지문은 운동을 하지 말라고 하지 않고 안전하게 운동하라고 했으므로 '운동을 하지 않는 것이 낫다'는 내용과 다릅니다.", "오답: 지문은 처음 운동을 시작하는 사람도 무리하면 다칠 수 있다고 했으므로 '운동을 시작하면 다치지 않는다'는 내용과 반대입니다."], "optExplainEn": ["Correct: The passage says experts advise choosing exercise that fits one's physical strength, so 'It is good to do exercise that fits one's physical strength' matches the content.", "Wrong: The passage says people may get injured if they overdo exercise, not that everyone who exercises gets injured.", "Wrong: The passage does not say not to exercise; rather it advises exercising safely, so 'It is better not to exercise' is different.", "Wrong: The passage warns that beginners can get injured if they overdo it, so 'If you start exercising, you will not get injured' is opposite to the text."], "tipEn": "For 'choose the same content' questions, compare each option with the passage word by word and avoid extreme words like '누구나' (everyone) or '절대로' (never).", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 내용 일치", "id": "AIII-ae34b2"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 2, "q": "윗글의 내용과 같은 것을 고르십시오.", "qGl": "Choose the statement that matches the passage.", "passage": "최근 직장인들 사이에서 혼자 점심을 먹는 사람이 늘고 있다. 바쁜 업무 때문에 동료와 시간을 맞추기가 어려워졌기 때문이다. 혼자 먹으면 시간을 아낄 수 있고 편하다는 장점이 있다. 하지만 같이 먹으며 나누는 대화가 줄어들면서 동료들과의 관계가 멀어질 수 있다는 걱정도 나온다.", "passageGl": "Recently, the number of office workers who eat lunch alone is increasing. This is because busy work has made it difficult to match schedules with colleagues. Eating alone has the advantage of saving time and being comfortable. However, as conversations shared while eating together decrease, there is also concern that relationships with colleagues may grow distant.", "options": [{"t": "직장인들은 예전부터 혼자 점심을 먹었다.", "gl": "Office workers have always eaten lunch alone."}, {"t": "바쁜 업무 때문에 혼자 먹는 사람이 늘었다.", "gl": "More people eat alone because of busy work."}, {"t": "혼자 점심을 먹으면 동료와 대화가 늘어난다.", "gl": "Eating lunch alone increases conversation with colleagues."}, {"t": "동료와의 관계가 가까워질까 봐 걱정한다.", "gl": "They worry that relationships with colleagues will get closer."}], "correct": 1, "explain": "The passage states that '바쁜 업무 때문에 동료와 시간을 맞추기가 어려워졌기 때문이다' and that '혼자 점심을 먹는 사람이 늘고 있다.' Therefore, the correct answer is that more people are eating alone because of busy work.", "traps": ["Option 1 is wrong: the passage says this is a recent trend, not something that has always happened.", "Option 3 reverses the passage: eating alone reduces conversation, not increases it.", "Option 4 is wrong: the concern is that relationships may become distant, not closer."], "tip": "For content-matching questions, compare each option against the passage sentence by sentence. Watch for words that changed meaning, such as '늘어난다' vs '줄어든다' or '가까워질까' vs '멀어질 수 있다'.", "optExplain": ["오답: 이 글은 혼자 점심을 먹는 사람이 최근에 늘고 있다고 했으므로 예전부터 그랬다는 것은 글의 내용과 다릅니다.", "정답: 바쁜 업무 때문에 동료와 시간을 맞추기 어려워져서 혼자 점심을 먹는 사람이 늘었다고 했으므로 글의 내용과 같습니다.", "오답: 혼자 먹으면 같이 먹으며 나누는 대화가 줄어든다고 했으므로 대화가 늘어난다는 것은 틀립니다.", "오답: 동료들과의 관계가 멀어질 수 있다는 걱정이 나온다고 했으므로 가까워질까 봐 걱정한다는 것은 틀립니다."], "optExplainEn": ["Wrong: The passage says people eating lunch alone have recently increased, so saying it has always been that way does not match.", "Correct: The passage says that because busy work makes it hard to match schedules with colleagues, more people eat lunch alone, so this matches.", "Wrong: The passage says conversations shared while eating together decrease, so saying conversation increases is incorrect.", "Wrong: The passage mentions concern that relationships may grow distant, so worrying they will get closer is incorrect."], "tipEn": "For content-matching questions, compare each option against the passage sentence by sentence. Watch for words that changed meaning, such as '늘어난다' vs '줄어든다' or '가까워질까' vs '멀어질 수 있다'.", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 내용 일치", "id": "AIII-741421"}, {"section": "listening", "type": "grammar", "level": 3, "points": 2, "q": "가: 어제 도서관에서 공부하다가 갑자기 코피가 나서 화장실로 뛰어갔어요. 나: 괜찮았어요? 요즘 너무 무리했나 봐요. 질문: 들은 내용과 같은 것을 고르십시오.", "qGl": "A: Yesterday, while studying at the library, I suddenly got a nosebleed and ran to the bathroom. B: Were you okay? You seem to have overdone it lately. Question: Choose the statement that matches what you heard.", "passage": "", "passageGl": "", "audioHint": "도서관에서 공부하다가 갑자기 코피가 나서 화장실로 뛰어갔다.", "options": [{"t": "도서관에서 계속 공부했다.", "gl": "He kept studying at the library."}, {"t": "공부하다가 코피가 나서 화장실로 뛰어갔다.", "gl": "He was studying when he got a nosebleed and ran to the bathroom."}, {"t": "코피가 나서 병원에 입원했다.", "gl": "He got a nosebleed and was hospitalized."}, {"t": "공부를 하지 않고 집에 있었다.", "gl": "He stayed home without studying."}], "correct": 1, "explain": "The dialogue says the man was studying at the library, suddenly got a nosebleed, and ran to the bathroom. This matches the grammar -다가, which shows an action interrupted by another event.", "traps": ["It ignores the interruption caused by the nosebleed.", "It adds hospitalization, which was not mentioned.", "It contradicts the fact that he went to the library."], "tip": "Listen for -다가; it signals that an action stopped or changed because of a new event.", "optExplain": ["오답: 남자는 공부를 계속하지 않고 코피가 나서 중단했습니다.", "정답: 남자가 도서관에서 공부하다가 코피가 나서 화장실로 뛰어갔다고 했습니다.", "오답: 병원에 입원했다는 내용은 대화에 없습니다.", "오답: 남자는 도서관에 갔으므로 집에 있었다는 말과 다릅니다."], "optExplainEn": ["Wrong: The man did not keep studying; he stopped because of a nosebleed.", "Correct: The man was studying at the library when he got a nosebleed and ran to the bathroom.", "Wrong: Hospitalization is not mentioned in the dialogue.", "Wrong: He went to the library, so this contradicts staying home."], "tipEn": "Listen for -다가; it signals that an action stopped or changed because of a new event.", "freq": 2, "freqNote": "TOPIK II 듣기 10~12 · 짧은 대화 세부 내용 파악", "id": "AIII-d055d7"}, {"section": "listening", "type": "topic", "level": 3, "points": 2, "q": "가: 다음 주부터 새로 시작하는 프로젝트 때문에 요즘 계속 야근이에요. 나: 저도 마감이 얼마 안 남아서 주말에도 출근해야 할 것 같아요. 가: 팀원들끼리 역할을 나누면 좀 나아질까요? 나: 그래도 일정이 빠듯해서 쉽지 않을 거예요. 질문: 무엇에 대해 이야기하고 있습니까?", "qGl": "A: I've been working late every day because of the new project starting next week. B: Me too. The deadline is near, so I'll probably have to go to work on the weekend. A: Would it get better if we divide roles among team members? B: Still, the schedule is tight, so it won't be easy. Question: What are they talking about?", "passage": "", "passageGl": "", "audioHint": "야근과 주말 출근 때문에 일이 많아 힘들다는 이야기.", "options": [{"t": "주말 여행 계획", "gl": "Weekend travel plans"}, {"t": "새 프로젝트 팀원 소개", "gl": "Introducing new project team members"}, {"t": "일이 많아서 힘든 상황", "gl": "A difficult situation due to heavy workload"}, {"t": "회사 근처 식당 추천", "gl": "Recommending a restaurant near work"}], "correct": 2, "explain": "The two speakers repeatedly mention overtime, weekend work, deadlines, and a tight schedule. The overall topic is how they are struggling with a heavy workload.", "traps": ["The dialogue is not about making travel plans.", "It is not introducing team members; it is about work pressure.", "No restaurant recommendation appears at all."], "tip": "In topic questions, listen for repeated words like 야근, 출근, 일정, 마감. Focus on the overall situation rather than one word.", "optExplain": ["오답: 여행 계획을 정하는 내용이 아닙니다.", "오답: 팀원 소개가 아니라 업무 부담에 대한 이야기입니다.", "정답: 야근과 주말 출근을 말하며 일이 많아 힘들다는 상황을 이야기하고 있습니다.", "오답: 식당 추천은 전혀 나오지 않았습니다."], "optExplainEn": ["Wrong: They are not planning a trip.", "Wrong: They are not introducing team members; they are talking about workload.", "Correct: They mention overtime and weekend work, showing a difficult workload situation.", "Wrong: There is no restaurant recommendation."], "tipEn": "In topic questions, listen for repeated words like overtime, going to work, schedule, and deadline. Focus on the overall situation rather than one word.", "freq": 2, "freqNote": "TOPIK II 듣기 4~6 · 대화 주제 파악", "id": "AIII-39f1c8"}, {"section": "listening", "type": "comprehension", "level": 3, "points": 2, "q": "가: 이번 주말에 같이 등산 갈래요? 날씨가 좋을 것 같아요. 나: 좋아요. 그런데 저는 등산화가 없어서 불편할 것 같아요. 가: 괜찮아요. 제가 여분 등산화를 하나 빌려 드릴 수 있어요. 나: 정말요? 그럼 등산 초보인 저도 편하게 다녀올 수 있겠네요. 가: 네, 등산로도 쉬운 코스로 정할게요. 질문: 여자가 이번 주말에 무엇을 할 것입니까?", "qGl": "A: Do you want to go hiking together this weekend? The weather looks nice. B: Sure, but I don't have hiking boots, so I might be uncomfortable. A: That's okay. I can lend you an extra pair of hiking boots. B: Really? Then even a beginner like me can go comfortably. A: Yes, and I'll pick an easy trail too. Question: What will the woman do this weekend?", "passage": "", "passageGl": "", "audioHint": "주말에 여자가 남자와 함께 등산을 가기로 했다.", "options": [{"t": "등산화를 사러 갈 것이다.", "gl": "She will go to buy hiking boots."}, {"t": "남자와 함께 등산을 갈 것이다.", "gl": "She will go hiking with the man."}, {"t": "등산 대신 영화를 볼 것이다.", "gl": "She will watch a movie instead of hiking."}, {"t": "집에서 쉴 것이다.", "gl": "She will rest at home."}], "correct": 1, "explain": "The woman agrees to go hiking with the man. She does not buy boots; the man offers to lend her an extra pair, and he says he will choose an easy trail.", "traps": ["She is not buying hiking boots; she will borrow them.", "Watching a movie is never mentioned.", "She is not staying home; she agreed to go hiking."], "tip": "For detail questions, note who offers help and what is finally decided. The final decision usually determines the answer.", "optExplain": ["오답: 등산화를 사는 것이 아니라 남자에게 빌린다고 했습니다.", "정답: 여자가 등산화를 빌리고 남자와 함께 등산을 가기로 했습니다.", "오답: 영화를 보자는 말은 나오지 않았습니다.", "오답: 집에서 쉰다는 말은 없고 주말에 등산을 가기로 했습니다."], "optExplainEn": ["Wrong: She will borrow hiking boots, not buy them.", "Correct: The woman will borrow hiking boots and go hiking with the man.", "Wrong: Watching a movie is not mentioned.", "Wrong: She is not staying home; she agreed to go hiking."], "tipEn": "For detail questions, note who offers help and what is finally decided. The final decision usually determines the answer.", "freq": 2, "freqNote": "TOPIK II 듣기 13~15 · 대화 후 할 일/상황 파악", "id": "AIII-c7ec65"}, {"section": "listening", "type": "grammar", "level": 3, "points": 3, "q": "여자: 요즘 밤마다 잠을 잘 못 자서 회사에서 계속 졸려요.\n남자: 이번 주말에는 푹 쉬었으면 좋겠어요.\n질문: 남자의 말에 나타난 마음으로 알맞은 것을 고르십시오.", "qGl": "Woman: Lately I can't sleep well at night, so I keep feeling sleepy at work.\nMan: I hope you can rest well this weekend.\nQuestion: Choose the feeling shown in the man's words.", "passage": "", "passageGl": "", "audioHint": "여자: 요즘 잠을 못 자서 계속 졸려요.\n남자: 주말에는 푹 쉬었으면 좋겠어요.", "options": [{"t": "바람", "gl": "wish/hope"}, {"t": "후회", "gl": "regret"}, {"t": "계획", "gl": "plan"}, {"t": "습관", "gl": "habit"}], "correct": 0, "explain": "The man says '이번 주말에는 푹 쉬었으면 좋겠어요,' using the grammar -았/었으면 좋겠다, which expresses a hope or wish. He is not expressing regret, making a plan, or describing a habit.", "traps": ["후회(regret) refers to feeling sorry about the past, not hoping for future rest.", "계획(plan) implies a fixed arrangement, but the man is only expressing a wish.", "습관(habit) means a repeated behavior, which does not match the one-time wish."], "tip": "Study the pattern '-았/었으면 좋겠다' as a way to express wishes or hopes; it often appears in listening questions about a speaker's emotional state or intention.", "optExplain": ["정답: '-았/었으면 좋겠다'는 어떤 일이 이루어지기를 바라는 마음을 나타내므로 '바람'이 맞습니다.", "오답: '후회'는 이미 지나간 일에 대해 아쉬워하는 마음이므로 대화와 어울리지 않습니다.", "오답: '계획'은 앞으로 할 일을 미리 정하는 것이므로 '기대'나 '소망'과는 다릅니다.", "오답: '습관'은 반복적인 행동을 뜻하므로 이 말에 해당하지 않습니다."], "optExplainEn": ["Correct: '-았/었으면 좋겠다' expresses a wish, so 'wish/hope' is correct.", "Wrong: 'Regret' is about feeling sorry for the past, which does not fit the dialogue.", "Wrong: 'Plan' means a fixed intention, not a wish or hope.", "Wrong: 'Habit' refers to repeated behavior, not the man's one-time wish."], "tipEn": "Study the pattern '-았/었으면 좋겠다' as a way to express wishes or hopes; it often appears in listening questions about a speaker's emotional state or intention.", "freq": 2, "freqNote": "TOPIK II 듣기 16~20 · 대화 속 표현의 의미", "id": "AIII-dafaf0"}, {"section": "listening", "type": "intent", "level": 3, "points": 3, "q": "여자: 주말인데 어디에 가려고?\n남자: 도서관에 가서 다음 주 시험 준비를 좀 하려고요.\n여자: 그럼 밥은 언제 먹을 거야?\n남자: 도서관 앞 식당에서 간단히 먹을게요.\n질문: 남자가 지금 하려는 일로 알맞은 것을 고르십시오.", "qGl": "Woman: It's the weekend, so where are you going?\nMan: I'm going to the library to prepare for next week's exam.\nWoman: Then when will you eat?\nMan: I'll eat simply at the restaurant in front of the library.\nQuestion: Choose what the man is trying to do now.", "passage": "", "passageGl": "", "audioHint": "여자: 주말인데 어디에 가려고?\n남자: 도서관에서 시험 준비를 하려고요.", "options": [{"t": "시험을 준비하려고 한다", "gl": "to prepare for an exam"}, {"t": "도서관에서 책을 빌리려고 한다", "gl": "to borrow a book from the library"}, {"t": "주말에 여행을 가려고 한다", "gl": "to go on a trip on the weekend"}, {"t": "식당에서 아르바이트를 하려고 한다", "gl": "to work part-time at a restaurant"}], "correct": 0, "explain": "The man clearly states he is going to the library to prepare for next week's exam. The other actions—borrowing a book, traveling, or working part-time—are not mentioned.", "traps": ["Borrowing a book is a possible library activity but is not stated.", "Traveling is not mentioned at all in the dialogue.", "The restaurant is only where he will eat; there is no mention of a part-time job."], "tip": "Listen carefully for '-려고요' and '-려고 하다' because they signal the speaker's intention or immediate plan.", "optExplain": ["정답: 남자가 도서관에 가서 다음 주 시험 준비를 하려고 했으므로 '시험을 준비하려고 한다'가 맞습니다.", "오답: 책을 빌린다는 내용은 대화에 나오지 않습니다.", "오답: 여행에 대한 언급은 전혀 없습니다.", "오답: 식당은 밥을 먹는 장소일 뿐 아르바이트 계획은 없습니다."], "optExplainEn": ["Correct: The man says he is going to prepare for next week's exam, so this is correct.", "Wrong: Borrowing a book is not mentioned.", "Wrong: Traveling is not mentioned.", "Wrong: The restaurant is only a place to eat, not a part-time job."], "tipEn": "Listen carefully for '-려고요' and '-려고 하다' because they signal the speaker's intention or immediate plan.", "freq": 2, "freqNote": "TOPIK II 듣기 9~12 · 화자의 의도 파악", "id": "AIII-4578d0"}, {"section": "listening", "type": "intent", "level": 3, "points": 3, "q": "여자: 방학에 뭐 할 거예요?\n남자: 한국어를 배우려고 어학당에 다닐 생각이에요.\n여자: 그래서 저번에 한국어 책을 산 거군요.\n남자: 네, 미리 공부해 놓으려고요.\n질문: 남자가 방학에 하려는 일로 알맞은 것을 고르십시오.", "qGl": "Woman: What will you do during the vacation?\nMan: I'm planning to attend a language school to learn Korean.\nWoman: So that's why you bought a Korean book the other day.\nMan: Yes, I wanted to study in advance.\nQuestion: Choose what the man plans to do during the vacation.", "passage": "", "passageGl": "", "audioHint": "남자: 방학에 한국어를 배우려고 어학당에 다닐 생각이에요.\n여자: 그래서 한국어 책을 샀군요.", "options": [{"t": "한국어를 배우려고 한다", "gl": "to learn Korean"}, {"t": "한국에 취직하려고 한다", "gl": "to get a job in Korea"}, {"t": "책을 쓰려고 한다", "gl": "to write a book"}, {"t": "어학당에서 가르치려고 한다", "gl": "to teach at a language school"}], "correct": 0, "explain": "The man says he plans to attend a language school to learn Korean and bought a Korean book to study in advance. Therefore his intended action is learning Korean.", "traps": ["Getting a job in Korea is not mentioned.", "Writing a book is not mentioned.", "He wants to learn, not teach, at the language school."], "tip": "For intention questions, focus on expressions like '-(으)려고', '-ㄹ 생각이다', and '-아/어 놓다' to identify what the speaker plans to do.", "optExplain": ["정답: 남자가 '한국어를 배우려고 어학당에 다닐 생각이에요'라고 했으므로 '한국어를 배우려고 한다'가 맞습니다.", "오답: 한국 취직에 대한 내용은 대화에 나오지 않습니다.", "오답: 책을 쓴다는 내용은 대화에 나오지 않습니다.", "오답: 남자는 어학당에서 배우려는 것이지 가르치려는 것이 아닙니다."], "optExplainEn": ["Correct: The man says he plans to attend a language school to learn Korean, so this is correct.", "Wrong: Getting a job in Korea is not mentioned.", "Wrong: Writing a book is not mentioned.", "Wrong: The man wants to learn, not teach, at the language school."], "tipEn": "For intention questions, focus on expressions like '-(으)려고', '-ㄹ 생각이다', and '-아/어 놓다' to identify what the speaker plans to do.", "freq": 2, "freqNote": "TOPIK II 듣기 9~12 · 화자의 의도 파악", "id": "AIII-48a4d4"}, {"section": "listening", "type": "place", "level": 3, "points": 3, "q": "가: 이번 주말에 등산 갈까요? 나: 좋아요. 그런데 날씨가 추우니까 옷을 따뜻하게 입으세요. 가: 네, 장갑이랑 목도리도 챙길게요. 나: 그럼 주말 아침에 산 입구에서 만나요. 가: 알겠습니다. 그때 봐요. 질문: 두 사람이 주말에 만날 장소는 어디입니까?", "qGl": "A: Shall we go hiking this weekend? B: Sure. But since it's cold, please dress warmly. A: Okay, I'll bring gloves and a scarf. B: Then let's meet at the mountain entrance on weekend morning. A: Got it. See you then. Question: Where will the two people meet on the weekend?", "passage": "", "passageGl": "", "options": [{"t": "산 입구", "gl": "mountain entrance"}, {"t": "산 정상", "gl": "mountain top"}, {"t": "회사 정문", "gl": "company main gate"}, {"t": "버스 터미널", "gl": "bus terminal"}], "correct": 0, "explain": "The male speaker explicitly says '산 입구에서 만나요' (Let's meet at the mountain entrance). Therefore, the meeting place is the mountain entrance.", "traps": ["Mountain top is not mentioned as the meeting place; it is a similar-sounding location but not what was said.", "The company gate is unrelated to the weekend hiking meeting.", "The bus terminal is not mentioned at all in the dialogue."], "tip": "장소 고르기 문제에서는 대화 속 장소 명사를 놓치지 말고, '어디에서 만나요'와 같은 표현 뒤에 나오는 장소에 집중하세요.", "optExplain": ["정답: 남자가 '산 입구에서 만나요'라고 했으므로 만날 장소는 산 입구입니다.", "오답: 산 정상은 대화에 나오지 않았고, 만날 장소로 언급되지 않았습니다.", "오답: 회사 정문은 두 사람이 주말에 만날 장소와 관련이 없습니다.", "오답: 버스 터미널은 대화에 나오지 않았습니다."], "optExplainEn": ["Correct: The man says 'Let's meet at the mountain entrance,' so the meeting place is the mountain entrance.", "Wrong: The mountain top is not mentioned in the dialogue as the meeting place.", "Wrong: The company main gate is not related to the weekend meeting place.", "Wrong: The bus terminal is not mentioned in the dialogue."], "tipEn": "In place questions, don't miss the location nouns in the dialogue. Focus on the place that follows expressions like '어디에서 만나요'.", "freq": 2, "freqNote": "TOPIK II 듣기 1~3 · 장소 고르기", "audioHint": "가: 이번 주말에 등산 갈까요? 나: 좋아요. 그럼 주말 아침에 산 입구에서 만나요.", "id": "AIII-0843c2"}, {"section": "listening", "type": "grammar", "level": 3, "points": 3, "q": "가: 이번 주말에 같이 영화 볼래요? 나: 미안해요. 요즘 일이 너무 많아서 야근을 할 수밖에 없어요. 질문: 여자의 말의 의미로 알맞은 것을 고르십시오.", "qGl": "A: Do you want to see a movie with me this weekend? B: Sorry, I have so much work these days that I have no choice but to work overtime. Question: Choose the option that best expresses the woman's meaning.", "passage": "", "passageGl": "", "options": [{"t": "영화를 보러 갈 수 있다.", "gl": "She can go see a movie."}, {"t": "야근을 하지 않아도 된다.", "gl": "She doesn't have to work overtime."}, {"t": "야근을 반드시 해야 한다.", "gl": "She has no choice but to work overtime."}, {"t": "일이 벌써 끝났다.", "gl": "The work is already finished."}], "correct": 2, "explain": "The woman uses '-(으)ㄹ 수밖에 없다', which expresses an unavoidable obligation or no choice. Because she has too much work, she must work overtime.", "traps": ["She says she cannot go to the movie, not that she can.", "The grammar implies obligation, not permission to skip work.", "The dialogue does not say the work is already finished; she says she has to work overtime."], "tip": "청취에서 문법 표현이 들리면 그 의미를 바로 연결하세요. '-(으)ㄹ 수밖에 없다'는 '반드시 ~해야 한다'로 바꿔 이해하면 쉽습니다.", "optExplain": ["오답: 여자는 주말에 영화를 볼 수 있다고 말하지 않았습니다.", "오답: 여자는 야근을 하지 않아도 된다고 말하지 않았습니다.", "정답: ‘-(으)ㄹ 수밖에 없다’는 반드시 해야 한다는 뜻이므로 야근을 반드시 해야 한다는 의미입니다.", "오답: 일이 끝났다는 내용은 대화에 나오지 않았습니다."], "optExplainEn": ["Wrong: The woman did not say she can see a movie on the weekend.", "Wrong: The woman did not say she doesn't have to work overtime.", "Correct: The expression '-(으)ㄹ 수밖에 없다' means 'have no choice but to', so she must work overtime.", "Wrong: The dialogue does not say the work is already finished."], "tipEn": "When you hear a grammar expression, connect its meaning immediately. '-(으)ㄹ 수밖에 없다' can be understood as 'must do'.", "freq": 2, "freqNote": "TOPIK II 듣기 4~6 · 문법 표현 고르기", "audioHint": "가: 주말에 영화 볼래요? 나: 미안해요. 일이 많아서 야근을 할 수밖에 없어요.", "id": "AIII-4b2f08"}];
